#!/usr/bin/env python3
"""Extract SIGNAL's title page from the founder's reference build, verbatim, into apps/demo/src/signal/titlepage.gen.ts.

The reference build (signal-standalone.html, SHA-256 80f8d992…) is engineer-private and is read as text only; it is never executed.
The title page is the founder's own work, like the panels in packages/signal-canon. Run with:  python3 -I scripts/signal/extract-titlepage.py <standalone.html>
"""
import sys, re, json, hashlib
src = sys.argv[1]; raw = open(src, 'rb').read(); sha = hashlib.sha256(raw).hexdigest(); t = raw.decode('utf-8')
i = t.index('<section class="titlepage" id="title"'); j = t.index('</section>', i); sec = t[i:j]
def between(s, a, b, start=0):
    x = s.index(a, start) + len(a); return s[x:s.index(b, x)]
cover = between(sec, '<figure class="tp-cover">', '</figure>').strip()
assert cover.startswith('<svg') and cover.endswith('</svg>') and 'base64' not in cover and '<script' not in cover and 'http' not in cover.replace('http://www.w3.org', '')
text = lambda s: re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', '', s)).strip().replace('&amp;', '&')
cast = []
for m in re.finditer(r'<div class="tp-card">(<svg.*?</svg>)<div><p class="tp-name">(.*?)</p><p class="tp-role">(.*?)</p></div></div>', sec, re.S):
    assert 'base64' not in m.group(1) and '<script' not in m.group(1); cast.append({'svg': m.group(1), 'name': text(m.group(2)), 'role': text(m.group(3))})
toc = [{'id': a, 'n': n, 'label': text(l)} for a, n, l in re.findall(r'<a href="#(pro\d\d)"><b>(\d\d)</b>(.*?)</a>', between(sec, '<nav class="tp-toc"', '</nav>'))]
arc = []
for m in re.finditer(r'<div class="tp-block" style="--c:(#[0-9A-Fa-f]{6})"><p class="tp-bl">(.*?)</p><div class="tp-ses">(.*?)</div></div>', sec, re.S):
    arc.append({'color': m.group(1), 'level': text(m.group(2)), 'seasons': [{'n': int(n), 'title': text(ti)} for n, ti in re.findall(r'href="#season-(\d+)"><b>S\d+</b><span>(.*?)</span>', m.group(3))]})
refs = sorted(set(re.findall(r'url\(#([^)]+)\)', cover)) | set(re.findall(r'href="#([^"]+)"', cover + ''.join(c['svg'] for c in cast)))); local = set(re.findall(r'\bid="([^"]+)"', cover))
data = {'source_sha256': sha, 'time': text(between(sec, '<p class="tp-time">', '</p>')), 'intro': text(between(sec, '<p class="tp-intro">', '</p>')),
        'kickers': [text(x) for x in re.findall(r'<p class="tp-kicker">(.*?)</p>', sec)], 'draft': text(between(sec, '<p class="tp-draft">', '</p>')), 'cast': cast, 'toc': toc, 'arc': arc,
        'alt': text(between(cover, '<title', '</title>').split('>', 1)[1]), 'needs': [r for r in refs if r not in local]}
assert len(cast) == 2 and len(toc) == 11 and sum(len(a['seasons']) for a in arc) == 12, (len(cast), len(toc), arc)
out = ('/** SIGNAL\'s title page, exactly as the founder\'s reference build draws it (signal-standalone.html, SHA-256 ' + sha[:16] + '…).\n'
       ' *  Generated by scripts/signal/extract-titlepage.py; do not edit by hand. The cover is the founder\'s own art. */\n'
       'export const TITLE_PAGE = ' + json.dumps(data, ensure_ascii=False, indent=1) + ' as const;\n'
       'export const COVER_SVG = ' + json.dumps(cover, ensure_ascii=False) + ';\n')
open(sys.argv[2], 'w', encoding='utf-8').write(out)
print('cover', len(cover), 'bytes; cast', [c['name'] for c in cast], '; toc', len(toc), '; needs', data['needs'], '; sha', sha[:16])
